"use strict";
// Example 1
let multiply = (a, b) => {
    return a * b;
};
console.log(multiply(5, 4));
let greetUser = (userName) => {
    return `Hello ${userName}`;
};
console.log(greetUser("Tovino"));
let add1 = (x, y) => x + y;
let sub = (x, y) => x - y;
let mul2 = (x, y) => x * y;
console.log(add1(10, 5));
console.log(sub(10, 5));
console.log(mul2(10, 5));
